using System.Diagnostics; using System.IO; using System.Windows; using System.Windows.Controls; namespace ASimpleMinecraftServer.UI.Pages; public partial class FirstRunWizardView:UserControl { public event EventHandler? CreateServerRequested; public FirstRunWizardView(){InitializeComponent();} private void Create_Click(object sender,RoutedEventArgs e)=>CreateServerRequested?.Invoke(this,EventArgs.Empty); private void Check_Click(object sender,RoutedEventArgs e){JavaStatusText.Text=FindJava()?"Java: detected":"Java: not detected — the server wizard can help select or install a compatible runtime.";var root=@"C:\GameServers";try{Directory.CreateDirectory(root);FolderStatusText.Text=$"Server folder: ready ({root})";}catch(Exception ex){FolderStatusText.Text=$"Server folder: needs attention ({ex.Message})";}var gb=GC.GetGCMemoryInfo().TotalAvailableMemoryBytes/1024d/1024d/1024d;MemoryStatusText.Text=$"Available system memory reported to .NET: {gb:N1} GB";} private static bool FindJava(){try{var psi=new ProcessStartInfo("java","-version"){UseShellExecute=false,RedirectStandardError=true,CreateNoWindow=true};using var p=Process.Start(psi);if(p is null)return false;p.WaitForExit(3000);return p.ExitCode==0;}catch{return false;}} }